const CALLING = { "1": "us", "44": "gb", "49": "de", "7": "ru" };

// A phone number from what a person typed, or null when it is not one. Never throws.
// Spaces, dashes, dots and brackets are ignored; the number starts with "+" and a calling code.
export function parsePhone(input) {
  if (typeof input !== "string") return null;
  const match = /^\+(\d{8,15})$/.exec(input.replace(/[\s\-.()]/g, ""));
  if (!match) return null;
  const code = Object.keys(CALLING).sort((a, b) => b.length - a.length).find((prefix) => match[1].startsWith(prefix));
  return code ? { e164: `+${match[1]}`, country: CALLING[code] } : null;
}
